/* NEET.info Counsellor Assist — demo frontend.
 *
 * Data comes from data/demo.json, generated by running the actual Python
 * prototype (export_site_data.py). Nothing on this page is hand-written.
 * The one piece of logic that runs live in the browser is the numeric guard:
 * a port of src/neetqa/guard.py and textnorm.py, so a visitor can try to sneak
 * a wrong fee past it.
 */
"use strict";

const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => Array.from(r.querySelectorAll(s));
const esc = (s) =>
  String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const inr = (n) =>
  n === null || n === undefined || Number.isNaN(Number(n))
    ? "—"
    : Number(n).toLocaleString("en-IN", { maximumFractionDigits: 2 });

let DATA = null;
const state = { tab: "ask", set: "all", lang: null, query: "", qid: null, job: null };
const TABS = ["ask", "guard", "capacity", "rank"];

/* ------------------------------------------------------------------ */
/* Numeric guard — port of guard.py + textnorm.py                      */
/* ------------------------------------------------------------------ */

const MULTIPLIERS = { lakh: 1e5, lakhs: 1e5, lac: 1e5, lacs: 1e5, crore: 1e7, crores: 1e7, thousand: 1e3 };

const stripIdentifiers = (t) =>
  String(t)
    .replace(/\b[A-Z]{2,}-[A-Z0-9-]{2,}\b/g, " ")
    .replace(/\b(20\d{2})\s*[-/]\s*(\d{2,4})\b/g, " ");

function extractAmounts(text) {
  const clean = stripIdentifiers(text);
  const re = /(\u20b9|Rs\.?|INR)?\s*(\d[\d,]*(?:\.\d+)?)\s*(lakhs?|lacs?|crores?|thousand|%|percent)?/gi;
  const out = [];
  let m;
  while ((m = re.exec(clean)) !== null) {
    const digits = (m[2] || "").replace(/,/g, "");
    if (!digits) continue;
    let value = parseFloat(digits);
    if (Number.isNaN(value)) continue;
    let unit = (m[3] || "").toLowerCase();
    let kind;
    if (MULTIPLIERS[unit]) {
      value *= MULTIPLIERS[unit];
      kind = "money";
      unit = unit.replace(/s$/, "");
    } else if (unit === "%" || unit === "percent") {
      kind = "percent";
    } else if (m[1]) {
      kind = "money";
    } else {
      kind = "count";
    }
    if (kind === "count" && Number.isInteger(value) && value >= 1950 && value <= 2099) kind = "year";
    out.push({ raw: m[0].trim(), value, kind });
  }
  return out;
}

const amountKey = (a) => `${a.kind}:${a.value.toFixed(2)}`;

function checkAnswer(answer, evidence) {
  const supported = new Set(extractAmounts(evidence).map(amountKey));
  const amounts = extractAmounts(answer);
  const unsupported = amounts.filter((a) => !supported.has(amountKey(a)));
  return { ok: unsupported.length === 0, unsupported, amounts, checked: amounts.length };
}

const isUnsupported = (a, list) => list.some((u) => amountKey(u) === amountKey(a));

/* ------------------------------------------------------------------ */
/* Rendering                                                           */
/* ------------------------------------------------------------------ */

function renderFindings() {
  const m = DATA.meta;
  const items = [
    [m.documents, "synthetic notices indexed"],
    [m.superseded, "superseded, never cited"],
    [m.questions, "test questions, two sets"],
    [`${m.resumes} / ${m.jobs}`, "resumes against posts"],
  ];
  $("#findings").innerHTML = items
    .map(([v, l]) => `<div class="finding"><b>${esc(inr(v))}</b><span>${esc(l)}</span></div>`)
    .join("");
  $("#statusText").textContent = `${m.documents} docs · ${m.chunks} chunks`;
}

function visibleQuestions() {
  const q = state.query.trim().toLowerCase();
  return DATA.questions.filter((it) => {
    if (state.set !== "all" && it.set !== state.set) return false;
    if (state.lang && it.lang !== state.lang) return false;
    if (q && !(it.question.toLowerCase().includes(q) || it.qid.toLowerCase().includes(q))) return false;
    return true;
  });
}

function renderList() {
  const rows = visibleQuestions();
  const list = $("#qlist");
  $("#qcount").textContent = `${rows.length} question${rows.length === 1 ? "" : "s"}`;
  if (!rows.length) {
    list.innerHTML = `<li><div class="empty">No question matches “${esc(state.query)}”.<br />Try <em>bond</em>, <em>kolkata</em> or <em>koto</em>.</div></li>`;
    return;
  }
  list.innerHTML = rows
    .map((it) => {
      const sel = it.qid === state.qid;
      return `<li><button class="q-item" data-qid="${esc(it.qid)}" aria-current="${sel}">
        <span class="q-top"><span class="q-id">${esc(it.qid)}</span><span class="q-text">${esc(it.question)}</span></span>
        <span class="q-tags">
          <span class="tag">${esc(it.set)}</span>
          <span class="tag">${esc(it.lang)}</span>
          ${it.answerable ? "" : '<span class="tag warn">unanswerable</span>'}
        </span></button></li>`;
    })
    .join("");
}

function renderAnswer() {
  const card = $("#answerCard");
  const it = DATA.questions.find((q) => q.qid === state.qid);
  if (!it) {
    card.innerHTML = `<div class="empty">Pick a question to see the answer, its citation and the guard verdict.</div>`;
    return;
  }
  const doc = DATA.corpus.find((d) => d.doc_id === it.citations[0]);
  const evidence = doc
    ? `<details class="evidence"><summary>Read the cited notice (${esc(doc.doc_id)})</summary><pre>${esc(doc.text)}</pre></details>`
    : "";
  const pills = [
    it.refused ? `<span class="pill bad">refused</span>` : `<span class="pill ok">answered</span>`,
    it.refused
      ? `<span class="pill neutral">guard: no figures</span>`
      : it.guardOk
      ? `<span class="pill ok">guard: every figure cited</span>`
      : `<span class="pill bad">guard: blocked</span>`,
    ...it.citations.map((c) => `<span class="pill cite">${esc(c)}</span>`),
  ].join("");
  const gold = it.gold.length ? it.gold.join(", ") : "none expected";

  card.innerHTML = `
    <p class="answer-q">${esc(it.question)}</p>
    <p class="answer-src">${esc(it.set)} set · ${esc(it.lang)}${it.session ? ` · filter session=${esc(it.session)}` : " · no session filter"}</p>
    <div class="bubble ${it.refused ? "refused" : ""}">${esc(it.answer)}</div>
    <div class="pills">${pills}</div>
    <dl class="facts">
      <div><dt>Why</dt><dd>${esc(it.reason || "composed from the cited document")}</dd></div>
      <div><dt>Gold document</dt><dd>${esc(gold)}</dd></div>
      <div><dt>Citations</dt><dd>${it.citations.length ? esc(it.citations.join(", ")) : "none — the answer is a refusal"}</dd></div>
    </dl>
    <div style="margin-top:14px;display:flex;gap:8px;flex-wrap:wrap">
      <button class="copy" id="copyCite" data-copy="${esc(it.citations.join(", "))}">Copy citation</button>
    </div>
    ${evidence}`;

  const copy = $("#copyCite");
  if (copy) {
    copy.addEventListener("click", async () => {
      const text = copy.dataset.copy || "";
      try {
        await navigator.clipboard.writeText(text);
      } catch {
        const t = document.createElement("textarea");
        t.value = text;
        document.body.appendChild(t);
        t.select();
        document.execCommand("copy");
        t.remove();
      }
      copy.textContent = "Copied";
      copy.classList.add("done");
      setTimeout(() => {
        copy.textContent = "Copy citation";
        copy.classList.remove("done");
      }, 1600);
    });
  }
}

/* ------------------------------ guard ------------------------------ */

function renderGuard() {
  const select = $("#gsource");
  select.innerHTML = DATA.corpus
    .filter((d) => d.doc_type === "bond_rule" || d.doc_type === "fee_notice")
    .map((d) => `<option value="${esc(d.doc_id)}">${esc(d.doc_id)} — ${esc(d.title)}</option>`)
    .join("");
  select.value = "DOC-BOND-HR-2627";
  $$("#gpresets .chip").forEach((b) =>
    b.addEventListener("click", () => {
      $$("#gpresets .chip").forEach((x) => x.classList.toggle("on", x === b));
      const p = b.dataset.preset;
      if (p === "incident1") {
        select.value = "DOC-BOND-HR-2627";
        $("#gannswer").value = "The bond amount for Haryana is INR 5 lakh. [DOC-BOND-HR-2627]";
      } else if (p === "ok") {
        select.value = "DOC-BOND-HR-2627";
        $("#gannswer").value =
          "The bond amount for Haryana is INR 10,00,000, for 2 years of rural or district hospital service. [DOC-BOND-HR-2627]";
      } else {
        select.value = "DOC-BOND-HR-2627";
        $("#gannswer").value = "The bond amount is INR 10 lakh. [DOC-BOND-HR-2627]";
      }
      runGuard();
    })
  );
  select.addEventListener("change", runGuard);
  $("#gannswer").addEventListener("input", runGuard);
  $("#gannswer").value = "The bond amount for Haryana is INR 5 lakh. [DOC-BOND-HR-2627]";
  $$("#gpresets .chip")[0].classList.add("on");
  runGuard();
}

function runGuard() {
  const docId = $("#gsource").value;
  const doc = DATA.corpus.find((d) => d.doc_id === docId);
  const answer = $("#gannswer").value;
  if (!doc) return;
  $("#gsourceId").textContent = docId;
  $("#gsourceText").textContent = doc.text;
  const res = checkAnswer(answer, doc.text);
  const box = $("#gresult");
  const chips = $("#gnumbers");

  if (!answer.trim()) {
    box.className = "verdict";
    box.textContent = "Type an answer above, or pick a preset.";
    chips.innerHTML = "";
    return;
  }
  if (res.ok) {
    box.className = "verdict ok";
    box.innerHTML = `<strong>Pass.</strong> All ${res.checked} figure${res.checked === 1 ? "" : "s"} in this answer appear in ${esc(docId)}. This answer would reach the family.`;
  } else {
    const bad = res.unsupported.map((a) => `<code>${esc(a.raw)}</code>`).join(" ");
    box.className = "verdict bad";
    box.innerHTML = `<strong>Blocked.</strong> ${res.unsupported.length} figure${
      res.unsupported.length === 1 ? "" : "s"
    } not present in the cited notice: ${bad}. The family would see a refusal with the citation instead.`;
  }
  chips.innerHTML = res.amounts
    .map((a) => {
      const bad = !res.ok && isUnsupported(a, res.unsupported);
      return `<span class="num ${bad ? "bad" : "ok"}" title="${bad ? "not in source" : "found in source"}">${esc(a.raw)}</span>`;
    })
    .join("");
}

/* ---------------------------- capacity ----------------------------- */

function table(headers, rows, numericFrom = 1) {
  const head = headers
    .map((h, i) => `<th class="${i >= numericFrom ? "num" : ""}">${esc(h)}</th>`)
    .join("");
  const body = rows
    .map(
      (r) =>
        `<tr>${r
          .map((cell, i) => `<td class="${i >= numericFrom ? "num" : ""}">${cell}</td>`)
          .join("")}</tr>`
    )
    .join("");
  return `<table><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table>`;
}

function renderCapacity() {
  const c = DATA.capacity;
  const t = c.tco;

  $("#capCallout").innerHTML = `
    <div class="big">${esc(inr(t.cost_per_1000_chats))}</div>
    <p><strong>INR per 1,000 chats, all in.</strong> Marginal cost of one more chat is
    INR ${esc(inr(t.marginal_per_1000 / 1000))}. ${esc(inr(t.people_share))}% of the three-year
    total is two people, and cloud is not cheaper — break-even is
    ${esc(inr(t.breakeven_chats_year))} chats a year against a forecast of 2.5–3.1 million.</p>`;

  $("#kvtable").innerHTML = table(
    ["Model", "Weights GB", "KV/token", "KV pool GB", "Chats in 48 GB"],
    c.kv
      .filter((r) => r.weights_bits === 4)
      .map((r) => [
        `<span class="hl">${esc(r.model)}</span>`,
        inr(r.weights_gb),
        `${inr(r.kv_kib_fp16)} KiB`,
        inr(r.kv_pool_gb),
        `<span class="hl">${r.seq_fp16}</span> / ${r.seq_int8}`,
      ]),
    1
  );

  $("#thrtable").innerHTML = table(
    ["Model", "1 stream", "Batched", "Prefill tok/s", "Seqs"],
    c.throughput.map((r) => [
      `<span class="hl">${esc(r.model)}</span>`,
      inr(r.decode_single),
      `<span class="hl">${inr(r.decode_real)}</span>`,
      inr(r.prefill_tok_s),
      inr(r.seqs),
    ]),
    1
  );

  $("#traftable").innerHTML = table(
    ["Scenario", "Chats/day", "Turns/s peak", "Prompt tok/s raw", "Prompt tok/s design", "Output tok/s"],
    c.traffic.map((r) => [
      `<span class="hl">${esc(r.scenario)}</span>`,
      inr(r.chats_day),
      inr(r.turns_s_peak),
      inr(r.prompt_tok_s_raw),
      `<span class="hl">${inr(r.prompt_tok_s_design)}</span>`,
      inr(r.output_tok_s),
    ]),
    1
  );

  const rows = [
    ["Three-year total, one GPU", `INR ${inr(t.one_card)}`, true],
    ["Three-year total, two GPUs", `INR ${inr(t.two_card)}`, false],
    ["Cash excluding the sunk workstation", `INR ${inr(t.cash_excl_sunk)}`, false],
    ["All-in cost per 1,000 chats", `INR ${inr(t.cost_per_1000_chats)}`, true],
    ["Marginal cost per 1,000 chats", `INR ${inr(t.marginal_per_1000)}`, false],
    ["People as a share of the total", `${inr(t.people_share)}%`, true],
    ["Cloud cost per chat", `INR ${inr(t.cloud_per_chat)}`, false],
    ["Break-even volume", `${inr(t.breakeven_chats_year)} chats / year`, true],
    ["Cost per resume (on-prem vs cloud)", `INR ${inr(t.onprem_per_resume)} vs ${inr(t.cloud_per_resume)}`, false],
    ["GPU-hours, full 240k backlog", `${inr(c.batch.total_h)} (weekly ${inr(c.batch.weekly_h)})`, false],
    ["Nights at 8 h", inr(c.batch.nights_at_8h), false],
    ["Spare GPU-hours sellable / year", `${inr(c.rental.sellable_h)} at INR ${inr(c.rental.price)}/h`, false],
  ];
  $("#tco").innerHTML = rows
    .map(([k, v, hi]) => `<div>${esc(k)}</div><div class="v ${hi ? "accent" : ""}">${esc(v)}</div>`)
    .join("");
}

/* ----------------------------- ranking ----------------------------- */

function fairnessBlock(d) {
  const rates = Object.entries(d.rates);
  const max = Math.max(...rates.map(([, v]) => v), 0.0001);
  const bars = rates
    .map(
      ([g, v]) =>
        `<div class="rate">
          <div class="rate-head"><b>${esc(g === "woman" ? "Women" : "Men")}</b><span class="muted small">${(v * 100).toFixed(
          1
        )}% selected · ${d.top[g] || 0} of ${d.pool[g] || 0}</span></div>
          <div class="bar"><i class="${g === "woman" ? "w" : "m"}" style="width:${((v / max) * 100).toFixed(1)}%"></i></div>
        </div>`
    )
    .join("");
  return `${bars}
    <div style="display:flex;align-items:center;gap:10px;margin-top:4px">
      <span class="ratio ${d.passes ? "ok" : "bad"}">ratio ${d.ratio.toFixed(2)} · ${d.passes ? "PASS" : "FAIL"}</span>
      <span class="muted small">four-fifths threshold 0.80</span>
    </div>`;
}

function renderRank() {
  const select = $("#jselect");
  const jobs = DATA.jobs;
  select.innerHTML = jobs.map((j) => `<option value="${esc(j.jid)}">${esc(j.post)} — ${esc(j.hospital)}</option>`).join("");
  if (!state.job) state.job = jobs[0].jid;
  select.value = state.job;
  select.onchange = () => {
    state.job = select.value;
    renderRank();
  };

  const job = jobs.find((j) => j.jid === state.job);
  if (!job) return;

  $("#ranktable").innerHTML = table(
    ["#", "Candidate", "Score", "Status", "Why"],
    job.ranked.map((r) => [
      esc(r.rank),
      `<span class="hl">${esc(r.name)}</span>`,
      r.score.toFixed(2),
      r.eligible ? `<span class="flag ok">eligible</span>` : `<span class="flag bad">ineligible</span>`,
      r.explanation.map((l) => `<span class="why">${esc(l)}</span>`).join(""),
    ]),
    2
  );

  $("#fairApplicant").innerHTML = fairnessBlock(job.fairness.applicant);
  $("#fairEligible").innerHTML = fairnessBlock(job.fairness.eligible);
}

/* ------------------------------ routing ---------------------------- */

function showTab(tab, push = true) {
  if (!TABS.includes(tab)) tab = "ask";
  state.tab = tab;
  $$(".tabs button").forEach((b) => {
    const on = b.dataset.tab === tab;
    b.classList.toggle("on", on);
    b.setAttribute("aria-selected", String(on));
    b.tabIndex = on ? 0 : -1;
  });
  $$(".panel").forEach((p) => p.classList.toggle("on", p.id === `panel-${tab}`));
  if (push) {
    const hash = tab === "ask" && state.qid ? `#ask/${state.qid}` : `#${tab}`;
    if (location.hash !== hash) history.replaceState(null, "", hash);
  }
}

function applyHash() {
  const raw = location.hash.replace(/^#/, "");
  const [tab, qid] = raw.split("/");
  if (qid && DATA.questions.some((q) => q.qid === qid)) state.qid = qid;
  showTab(TABS.includes(tab) ? tab : "ask", false);
}

function wire() {
  $$(".tabs button").forEach((b) => b.addEventListener("click", () => showTab(b.dataset.tab)));

  $("#qsearch").addEventListener("input", (e) => {
    state.query = e.target.value;
    renderList();
  });
  $("#qsearch").addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      const first = visibleQuestions()[0];
      if (first) {
        state.qid = first.qid;
        renderList();
        renderAnswer();
        showTab("ask");
      }
    }
  });

  $("#qlist").addEventListener("click", (e) => {
    const btn = e.target.closest("[data-qid]");
    if (!btn) return;
    state.qid = btn.dataset.qid;
    renderList();
    renderAnswer();
    showTab("ask");
  });

  $$("#qfilters .chip").forEach((b) =>
    b.addEventListener("click", () => {
      if (b.dataset.set) {
        state.set = b.dataset.set;
        $$('#qfilters .chip[data-set]').forEach((x) => x.classList.toggle("on", x === b));
      }
      if (b.dataset.lang) {
        const same = state.lang === b.dataset.lang;
        state.lang = same ? null : b.dataset.lang;
        b.classList.toggle("on", !same);
      }
      renderList();
    })
  );

  document.addEventListener("keydown", (e) => {
    const tag = (e.target.tagName || "").toLowerCase();
    const typing = tag === "input" || tag === "textarea" || tag === "select";
    if (e.key === "/" && !typing) {
      e.preventDefault();
      showTab("ask");
      $("#qsearch").focus();
      $("#qsearch").select();
    }
    if (e.key === "Escape" && tag === "input") {
      $("#qsearch").value = "";
      state.query = "";
      renderList();
      $("#qsearch").blur();
    }
  });

  window.addEventListener("hashchange", applyHash);
}

async function boot() {
  const res = await fetch("data/demo.json");
  if (!res.ok) throw new Error(`could not load demo.json (${res.status})`);
  DATA = await res.json();
  state.qid = DATA.questions[0].qid;
  renderFindings();
  renderGuard();
  renderCapacity();
  renderRank();
  wire();
  renderList();
  applyHash();
  renderAnswer();
}

boot().catch((err) => {
  $("#statusText").textContent = "offline";
  $("main").innerHTML = `<div class="shell"><div class="card" style="margin-top:28px">
    <h2>Could not load the demo data</h2>
    <p class="muted">${esc(err.message)}</p>
    <p class="muted small">The page expects <code>data/demo.json</code> beside it. Regenerate it with <code>python export_site_data.py</code>.</p>
  </div></div>`;
});
